package io.github.diodeme.ji.artifact;

import java.util.Locale;

/** Metadata for a resumable, fixed-size chunk upload. */
public record ResumableUpload(
        ArtifactScope scope, String mediaType, String displayName, long totalBytes, String sha256Hex) {
    public ResumableUpload {
        if (scope == null) throw new IllegalArgumentException("scope is required");
        if (mediaType == null || mediaType.isBlank()) throw new IllegalArgumentException("mediaType must not be blank");
        if (displayName == null || displayName.isBlank()) throw new IllegalArgumentException("displayName must not be blank");
        if (totalBytes < 0) throw new IllegalArgumentException("totalBytes must be non-negative");
        if (sha256Hex == null || !sha256Hex.matches("[0-9a-fA-F]{64}")) throw new IllegalArgumentException("sha256Hex is invalid");
        sha256Hex = sha256Hex.toLowerCase(Locale.ROOT);
    }
}
